insert into public.collectible_species ("id","kind","name","description","swim_y_min","swim_y_max","speed","size","rarity","thumbnail_path","sell_price","sprite_sheet_path","native_region_id","movement_type","flip_with_direction","travel_direction") values
('sandbar-guide-sawshark','fish','모래톱 길잡이','모래톱 사이로 길을 여는 작은 톱상어. 크림빛 주둥이에 난 톱니로 모래를 살피며 낯선 바다의 길잡이가 되어준다.','0.18','0.78','0.035',100,'rare','fish/rare/sandbar-guide-sawshark_thumbnail.png',210,'fish/rare/sandbar-guide-sawshark_sprite.png',null,'swim',true,'both'),
('napping-moon-sunfish','fish','낮잠달 개복치','낮잠을 좋아하는 둥근 개복치. 은빛 몸에 내려앉은 초승달 무늬가 잔물결을 받을 때마다 부드럽게 반짝인다.','0.18','0.78','0.035',104,'rare','fish/rare/napping-moon-sunfish_thumbnail.png',220,'fish/rare/napping-moon-sunfish_sprite.png',null,'swim',true,'both'),
('celadon-spiral-whelk','fish','청자나선 골뱅이','청자빛 나선 껍데기를 가진 골뱅이. 넓고 말랑한 발로 어항 앞유리에 붙어 바깥세상을 느긋하게 바라본다.','0.18','0.78','0.001',78,'rare','fish/rare/celadon-spiral-whelk_thumbnail.png',180,'fish/rare/celadon-spiral-whelk_sprite.png',null,'fixed',false,'both'),
('celadon-dewdrop-snail','fish','청자물방울 고둥','물방울처럼 둥근 청자색 껍데기의 고둥. 크림빛 발바닥을 유리에 붙이고 긴 더듬이로 물살의 작은 변화를 읽는다.','0.18','0.78','0.001',76,'rare','fish/rare/celadon-dewdrop-snail_thumbnail.png',190,'fish/rare/celadon-dewdrop-snail_sprite.png',null,'fixed',false,'both'),
('amber-lantern-snail','fish','호박등불 고둥','호박빛 껍데기 안에 작은 등불을 품은 고둥. 살구색 발바닥으로 앞유리에 붙어 바다의 저녁을 따뜻하게 밝힌다.','0.18','0.78','0.001',84,'rare','fish/rare/amber-lantern-snail_thumbnail.png',200,'fish/rare/amber-lantern-snail_sprite.png',null,'fixed',false,'both'),
('glass-dome-barreleye','fish','유리관 투명머리물고기','머리를 덮은 투명한 유리관 속에 초록빛 눈이 떠 있는 물고기. 작은 지느러미로 물살을 고르며 바다에 스며든 빛을 좇는다.','0.18','0.78','0.025',108,'epic','fish/epic/glass-dome-barreleye_thumbnail.png',650,'fish/epic/glass-dome-barreleye_sprite.png',null,'swim',true,'both'),
('night-pouch-gulper-eel','fish','밤주머니 풍선장어','밤을 담은 듯 검푸른 입주머니를 가진 풍선장어. 길게 흐르는 꼬리 끝의 호박빛 불꽃이 어두운 물길을 가만히 비춘다.','0.18','0.78','0.025',138,'epic','fish/epic/night-pouch-gulper-eel_thumbnail.png',720,'fish/epic/night-pouch-gulper-eel_sprite.png',null,'swim',true,'both'),
('living-fossil-coelacanth','fish','살아있는 화석 실러캔스','아득한 옛 바다의 모습을 간직한 실러캔스. 푸른 광석 같은 비늘과 두툼한 지느러미를 천천히 움직이며 긴 시간을 헤엄친다.','0.18','0.78','0.025',132,'epic','fish/epic/living-fossil-coelacanth_thumbnail.png',760,'fish/epic/living-fossil-coelacanth_sprite.png',null,'swim',true,'both'),
('meteor-tentacle-squid','fish','유성촉수 오징어','남보라빛 몸에 유성 같은 빛무늬가 흐르는 오징어. 긴 촉수가 물살을 따라 펼쳐질 때마다 푸른 빛줄기가 이어진다.','0.18','0.78','0.025',124,'epic','fish/epic/meteor-tentacle-squid_thumbnail.png',700,'fish/epic/meteor-tentacle-squid_sprite.png',null,'pulse',true,'both'),
('unmong-cloud-weaver','fish','운몽, 구름을 짜는 해파리','투명한 갓 안에서 구름을 짜는 오래된 해파리. 비처럼 드리운 촉수가 흩어진 꿈을 모아 바다 위의 새벽으로 돌려보낸다.','0.18','0.78','0.018',154,'mythic','fish/mythic/unmong-cloud-weaver_thumbnail.png',2200,'fish/mythic/unmong-cloud-weaver_sprite.png',null,'pulse',true,'both'),
('obel-sunken-crown','fish','오벨, 가라앉은 왕관','가라앉은 왕관을 닮은 백금 가시의 성게. 푸른 몸속에 잊힌 왕국의 빛을 간직하고 작은 관족으로 바다 바닥을 더듬는다.','0.80','0.93','0.018',130,'mythic','fish/mythic/obel-sunken-crown_thumbnail.png',2050,'fish/mythic/obel-sunken-crown_sprite.png',null,'crawl',true,'both'),
('god-devouring-leviathan','fish','신을 삼키는 레비아탄','신들마저 삼켰다고 전해지는 태초의 바다 거수. 왕관 같은 뿔과 흑청색 비늘 사이로 새어 나오는 빛이 심연의 물결을 가른다.','0.18','0.78','0.018',180,'mythic','fish/mythic/god-devouring-leviathan_thumbnail.png',2800,'fish/mythic/god-devouring-leviathan_sprite.png',null,'swim',true,'both')
insert into public.collectible_habitats(species_id,region_id) select s.id,r.id from public.collectible_species s cross join public.regions r where s.id in ('sandbar-guide-sawshark','napping-moon-sunfish','celadon-spiral-whelk','celadon-dewdrop-snail','amber-lantern-snail','glass-dome-barreleye','night-pouch-gulper-eel','living-fossil-coelacanth','meteor-tentacle-squid','unmong-cloud-weaver','obel-sunken-crown','god-devouring-leviathan');
