-- 공통 희귀 5종 + 특급 4종 + 신화 3종만 추가하는 한정 패치. 기존 전체 baseline/history는 실행하지 않습니다.
begin;
set local lock_timeout = '5s';
set constraints all deferred;
on conflict(id) do update set "kind"=excluded."kind","name"=excluded."name","description"=excluded."description","swim_y_min"=excluded."swim_y_min","swim_y_max"=excluded."swim_y_max","speed"=excluded."speed","size"=excluded."size","rarity"=excluded."rarity","thumbnail_path"=excluded."thumbnail_path","sell_price"=excluded."sell_price","sprite_sheet_path"=excluded."sprite_sheet_path","native_region_id"=excluded."native_region_id","movement_type"=excluded."movement_type","flip_with_direction"=excluded."flip_with_direction","travel_direction"=excluded."travel_direction";
delete from public.collectible_habitats where species_id in ('sandbar-guide-sawshark','napping-moon-sunfish','celadon-spiral-whelk','celadon-dewdrop-snail','amber-lantern-snail','glass-dome-barreleye','night-pouch-gulper-eel','living-fossil-coelacanth','meteor-tentacle-squid','unmong-cloud-weaver','obel-sunken-crown','god-devouring-leviathan');
update public.collectible_species set facing_direction=case when movement_type='fixed' then 'front' else 'right' end, idle_animated=false where id in ('sandbar-guide-sawshark','napping-moon-sunfish','celadon-spiral-whelk','celadon-dewdrop-snail','amber-lantern-snail','glass-dome-barreleye','night-pouch-gulper-eel','living-fossil-coelacanth','meteor-tentacle-squid','unmong-cloud-weaver','obel-sunken-crown','god-devouring-leviathan');
select s.id,s.name,s.rarity,s.movement_type,count(h.region_id)::integer as habitat_count from public.collectible_species s left join public.collectible_habitats h on h.species_id=s.id where s.id in ('sandbar-guide-sawshark','napping-moon-sunfish','celadon-spiral-whelk','celadon-dewdrop-snail','amber-lantern-snail','glass-dome-barreleye','night-pouch-gulper-eel','living-fossil-coelacanth','meteor-tentacle-squid','unmong-cloud-weaver','obel-sunken-crown','god-devouring-leviathan') group by s.id order by s.rarity,s.name;
commit;
